import subprocess, tempfile, os
EXE="/workspace/executable"
def imp_of(name):
    import tempfile
    td=tempfile.mkdtemp()
    # create as file (or dir for src?)
    if name=="src":
        os.makedirs(f"{td}/{name}", exist_ok=True)
    else:
        open(f"{td}/{name}","w").write("x")
    res={}
    for imp in ["0","1","2","3","4"]:
        out=subprocess.run([EXE,"--imp",imp], cwd=td, capture_output=True, text=True).stdout
        res[imp]= (name in out)
    # determine max imp where shown
    max_shown=-1
    for k,v in res.items():
        if v: max_shown=int(k)
    return max_shown, res

for name in ["README","README.md","README-foo","README.foo","README_foo","READMEfoo","readme","src","Src","SRC",".hidden",".gitignore","Cargo.lock","Cargo.toml","LICENSE","a.txt","Dockerfile","Makefile",".env","src.txt"]:
    print(name, imp_of(name))
PY"}

