                    let full = d.join(&fname);
                    // get metadata via symlink_metadata
                    let md = match std::fs::symlink_metadata(&full) {
                        Ok(m) => m,
                        Err(_) => continue,
                    };
                    let node = Node::from_metadata(fname.clone(), full.clone(), md);
                    nodes.push(node);
                }
                // filter: typ, imp, exclude, only, plus .git/.DS_Store via imp? Actually imp -1 shows them, so use imp logic.
                nodes = filter_nodes(nodes, &typ_set, imp, exclude_re.as_ref(), only_re.as_ref());
                // sort
                sort_nodes(&mut nodes, &sort_list);
