                            if out.ends_with("\n") { out.push('\n'); } else { out.push_str("\n"); }
                        }
                    } else {
                        out.push('\n');
                    }
                    out.push_str(&format!("{}:\n", dir_str));
                }
                // if det empty, just names (with grid? For piped, single column. For tty with grid true, multi-column)
                if det_list.is_empty() {
                    // plain listing
                    if grid && is_tty {
                        // grid layout (multi-column) - implement
                        let lines = format_grid(&display_nodes, show_icon, show_suffix, show_sym, align, down, color_enabled);
                        out.push_str(&lines);
                    } else {
                        for dn in display_nodes.iter() {
                            match dn {
                                DisplayNode::Single(n) => {
                                    let line = format_plain_node(n, show_icon, show_suffix, show_sym, align, color_enabled, false);
                                    out.push_str(&line);
                                    out.push('\n');
                                }
                                DisplayNode::Collapsed { principal, child } => {
                                    let line = format_plain_node(principal, show_icon, show_suffix, show_sym, align, color_enabled, false);
                                    out.push_str(&line);
                                    out.push('\n');
                                    // child with prefix "   └─ "
                                    let child_line = format_plain_node(child, show_icon, show_suffix, show_sym, align, color_enabled, true);
                                    out.push_str(&child_line);
                                    out.push('\n');
                                }
                            }
                        }
                    }
                } else {
                    // detail view: header + rows
                    let table = format_detail_table(&display_nodes, &det_list, &unit, header, show_icon, show_suffix, show_sym, align, color_enabled);
                    out.push_str(&table);
                }
            }
        }
    }
    print!("{}", out);
}

