    let mut set: Vec<String> = Vec::new();
    let all_vals = vec!["dir","symlink","fifo","socket","block-device","char-device","file"];
    for v in raw.iter() {
        if v=="none" {
            set.clear();
        } else if v=="all" {
            for e in all_vals.iter() {
                if !set.contains(&e.to_string()) { set.push(e.to_string()); }
            }
        } else {
            if !set.contains(v) { set.push(v.clone()); }
        }
    }
    // default ["all"] => all_vals. Good.
    set
}
