    // raw default ["cat","cname"] when no args. Need to handle none clearing, dedup move-to-end? For sort, none clears, others append with move-to-end? Earlier we saw size,name,size => name,size (move). So use move-to-end.
    let mut list: Vec<String> = Vec::new();
    for v in raw.iter() {
        if v=="none" {
            list.clear();
        } else {
            if let Some(pos)=list.iter().position(|x| x==v) { list.remove(pos); }
            list.push(v.clone());
        }
    }
    list
}
