        if v!="0" { return true; }
    }
    if std::env::var("NO_COLOR").is_ok() { return false; }
    if let Ok(v)=std::env::var("CLICOLOR") {
        if v=="0" { return false; }
    }
    unsafe { libc::isatty(1)==1 }
}
fn format_error(msg: &str) -> String {
    // msg is like "No such file or directory (os error 2)" or "Permission denied (os error 13)"
    // Original shows "error: No such file..." for dir read errors? Actually for single noperm dir, output was "error: Permission denied..." without tab? For explicit nonexistent, "error: ..." with tab? Let's handle in caller.
    // Here just return "error: ..." ?
    // The caller for explicit errors does format!("{}:\n\t{}\n", path, format_error)
    // For dir read errors, caller does format!("{}\n", format_error) or with header?
    // Let's make format_error return "error: ..." 
    if msg.contains("error:") { msg.to_string() } else { format!("error: {}", msg) }
}
