#[derive(Clone, Debug)]
struct Node {
    name: String,
    path: PathBuf,
    file_type: String, // dir, symlink, fifo, socket, block-device, char-device, file
    typ_char: char, // d,f,l,p,s,b,c,?
    metadata: std::fs::Metadata,
    symlink_target: Option<String>, // immediate readlink target string
}

impl Node {
    fn from_metadata(name: String, path: PathBuf, md: std::fs::Metadata) -> Self {
        let ft = md.file_type();
        let (file_type, typ_char) = if ft.is_dir() {
            ("dir".to_string(), 'd')
        } else if ft.is_symlink() {
            ("symlink".to_string(), 'l')
        } else if ft.is_fifo() {
            ("fifo".to_string(), 'p')
        } else if ft.is_socket() {
            ("socket".to_string(), 's')
        } else if ft.is_block_device() {
            ("block-device".to_string(), 'b')
        } else if ft.is_char_device() {
            ("char-device".to_string(), 'c')
        } else {
            ("file".to_string(), 'f')
        };
        let symlink_target = if ft.is_symlink() {
            std::fs::read_link(&path).ok().map(|p| p.to_string_lossy().to_string())
        } else { None };
        Node { name, path, file_type, typ_char, metadata: md, symlink_target }
    }
}

enum DisplayNode {
    Single(Node),
    Collapsed { principal: Node, child: Node },
}

fn importance(name: &str) -> i8 {
    if name==".git" || name==".DS_Store" { return -1; }
    if name=="Cargo.lock" { return 0; }
    if name.starts_with('.') { return 0; }
    if name=="README" || name.starts_with("README.") || name.starts_with("README-") { return 3; }
    if name=="src" { return 2; }
    1
}

fn filter_nodes(nodes: Vec<Node>, typ_set: &[String], imp: i8, exclude: Option<&Regex>, only: Option<&Regex>) -> Vec<Node> {
    let mut out = Vec::new();
    for n in nodes {
        // typ filter
        if !typ_set.contains(&n.file_type) { continue; }
        // imp filter: show if importance >= imp
        if importance(&n.name) < imp { continue; }
        if let Some(re)=exclude { if re.is_match(&n.name) { continue; } }
        if let Some(re)=only { if !re.is_match(&n.name) { continue; } }
        out.push(n);
    }
    out
}

fn sort_nodes(nodes: &mut Vec<Node>, sort_list: &[String]) {
    if nodes.len() < 2 {
        // still need to check panic? No panic for <2. Good.
        return;
    }
    // check for panic fields: if sort_list contains inode_ or nlinks_, trigger panic (via sort_field)
    for f in sort_list.iter() {
        if f=="inode_" || f=="nlinks_" {
            // need to panic only if sorting actually compares? For empty/single, no panic (already returned). For 2+, panic.
            crate::enums::sort_field::trigger_panic();
        }
    }
    // stable sort with multiple keys? Original uses primary first? We need to apply comparators in order: first is primary.
    // Rust sort is stable, so to get primary first, we can sort by last key first, then ... first last? Or use comparator that checks keys in order.
    // Use comparator that iterates sort_list in order.
    nodes.sort_by(|a,b| {
        for f in sort_list.iter() {
            let ord = compare_field(a,b,f);
            if ord != std::cmp::Ordering::Equal { return ord; }
        }
        std::cmp::Ordering::Equal
    });
}

fn compare_field(a: &Node, b: &Node, field: &str) -> std::cmp::Ordering {
    match field {
        "dev" => a.metadata.dev().cmp(&b.metadata.dev()),
        "ino" => a.metadata.ino().cmp(&b.metadata.ino()),
        "nlink" => a.metadata.nlink().cmp(&b.metadata.nlink()),
        "typ" => typ_order(&a.file_type).cmp(&typ_order(&b.file_type)),
        "cat" => cat_order(&a.file_type).cmp(&cat_order(&b.file_type)),
        "user" => user_name(a.metadata.uid()).cmp(&user_name(b.metadata.uid())),
        "uid" => a.metadata.uid().cmp(&b.metadata.uid()),
        "group" => group_name(a.metadata.gid()).cmp(&group_name(b.metadata.gid())),
        "gid" => a.metadata.gid().cmp(&b.metadata.gid()),
        "size" => file_size(&a).cmp(&file_size(&b)),
