#[derive(Clone, Debug)]
struct Node {
    name: String,
    path: PathBuf,
    file_type: String, // dir, symlink, fifo, socket, block-device, char-device, file
    typ_char: char, // d,f,l,p,s,b,c,?
    metadata: std::fs::Metadata,
    symlink_target: Option<String>, // immediate readlink target string
}

impl Node {
    fn from_metadata(name: String, path: PathBuf, md: std::fs::Metadata) -> Self {
        let ft = md.file_type();
        let (file_type, typ_char) = if ft.is_dir() {
            ("dir".to_string(), 'd')
        } else if ft.is_symlink() {
            ("symlink".to_string(), 'l')
        } else if ft.is_fifo() {
            ("fifo".to_string(), 'p')
        } else if ft.is_socket() {
            ("socket".to_string(), 's')
        } else if ft.is_block_device() {
            ("block-device".to_string(), 'b')
        } else if ft.is_char_device() {
            ("char-device".to_string(), 'c')
        } else {
            ("file".to_string(), 'f')
        };
        let symlink_target = if ft.is_symlink() {
            std::fs::read_link(&path).ok().map(|p| p.to_string_lossy().to_string())
        } else { None };
        Node { name, path, file_type, typ_char, metadata: md, symlink_target }
    }
}

enum DisplayNode {
    Single(Node),
    Collapsed { principal: Node, child: Node },
