fn format_detail_table_inner(nodes: &[DisplayNode], det_list: &[String], unit: &str, show_header: bool, show_icon: bool, show_suffix: bool, show_sym: bool, align: bool, is_explicit: bool) -> String {
    // Expand nodes to rows (for collapsed, two rows: principal and child with prefix)
    struct Row {
        node: Node,
        is_child: bool,
    }
    let mut rows: Vec<Row> = Vec::new();
    for dn in nodes {
        match dn {
            DisplayNode::Single(n) => rows.push(Row{node: n.clone(), is_child: false}),
            DisplayNode::Collapsed{principal, child} => {
                rows.push(Row{node: principal.clone(), is_child: false});
                rows.push(Row{node: child.clone(), is_child: true});
            }
        }
    }
    if rows.is_empty() {
        if show_header {
            // header only? For empty dir with det, show header line only? From test: empty dir with --det size gave "Size Name\n" (header only). Good.
            let headers = det_headers(det_list);
            // need to compute widths? With no rows, widths are header lengths? For Size with no rows, width is header "Size" (4)? But what about Size with no rows? Header "Size" width 4? Let's just generate header with minimal widths.
            // For empty, size column width = header len (4)? Actually for empty dir, size header? Let's see: empty dir with --det size gave "Size Name\n" (no leading spaces? Actually "Size Name" with no leading? For non-empty, header was "   Size Name" (3 leading). For empty, was "Size Name" (no leading)? From test: "mydir --det size" with empty dir gave "Size Name\n" (no leading). Hmm need to check.
            // Let's just handle empty as header with no padding (since no rows to determine width).
            // Simpler: if no rows, just show headers joined by space?
            let mut hline = String::new();
            for (i, h) in headers.iter().enumerate() {
                if i>0 { hline.push(' '); }
                hline.push_str(h);
            }
            hline.push_str(" Name\n");
            // Actually need to handle Size header with no rows? Header "Size" (4) vs "Name" (4). So "Size Name\n" is correct (no extra padding).
            return hline;
        } else {
            return String::new();
        }
    }
    // For each det, compute values and widths
    // We need to handle Size specially (number/unit split)
    // First, generate raw values for each row/col
    // For Size, generate (num_str, unit_str)
    let mut size_nums: Vec<String> = Vec::new();
    let mut size_units: Vec<String> = Vec::new();
    for r in rows.iter() {
        if r.node.file_type=="dir" {
            size_nums.push("".to_string());
            size_units.push("".to_string());
        } else {
            let sz = r.node.metadata.size();
            let (num, unit_str) = file_size_str(sz, unit);
            size_nums.push(num);
            size_units.push(unit_str);
        }
    }
    // Compute widths
    // Map det -> width, header, alignment
    // We'll compute for each det column
    struct ColInfo {
        header: String,
        width: usize,
        align_right: bool,
        // for size, need num_width, unit_width
        num_width: usize,
        unit_width: usize,
    }
    let mut cols: Vec<ColInfo> = Vec::new();
    for det in det_list.iter() {
        let header = det_header(det).to_string();
        match det.as_str() {
            "size" => {
                let max_num = size_nums.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                // Actually header "Size" len 4, but num width should be max num len, unit width max unit len, total = num_width+1+unit_width, header padded to total?
                // Let's compute num_width = max(num len), unit_width = max(unit len)
                let num_w = size_nums.iter().map(|s| s.len()).max().unwrap_or(0);
                let unit_w = size_units.iter().map(|s| s.len()).max().unwrap_or(0);
                let total = num_w + 1 + unit_w;
                let width = total.max(header.len());
                // For header padding, if width > header len, header right-aligned to width
                cols.push(ColInfo{header, width, align_right: true, num_width: num_w, unit_width: unit_w});
            },
            "dev" => {
                let vals: Vec<String> = rows.iter().map(|r| format!("{}", r.node.metadata.dev())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                cols.push(ColInfo{header, width: w, align_right: true, num_width: 0, unit_width: 0});
            },
            "ino" => {
                let vals: Vec<String> = rows.iter().map(|r| format!("{}", r.node.metadata.ino())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                // header "inode" vs "ino"? Actually det "ino" header is "inode" (5? Actually "inode" len 5). Wait det "ino" header is "inode"? From test: "--det ino" header was "    inode" (with leading spaces). The header string is "inode" (5), not "ino". Good. So det_header("ino") should return "inode".
                cols.push(ColInfo{header, width: w, align_right: true, num_width: 0, unit_width: 0});
            },
            "nlink" => {
                let vals: Vec<String> = rows.iter().map(|r| format!("{}", r.node.metadata.nlink())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                cols.push(ColInfo{header, width: w, align_right: true, num_width: 0, unit_width: 0});
            },
            "typ" => {
                let w = 1.max(header.len()); // header "T" len 1, values 1
                cols.push(ColInfo{header, width: w, align_right: false, num_width: 0, unit_width: 0});
            },
            "perm" => {
                let w = "Permissions".len(); // always 11
                cols.push(ColInfo{header, width: w, align_right: false, num_width: 0, unit_width: 0});
            },
            "oct" => {
                let vals: Vec<String> = rows.iter().map(|r| oct_str(r.node.metadata.mode())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                cols.push(ColInfo{header, width: w, align_right: true, num_width: 0, unit_width: 0});
            },
            "user" => {
                let vals: Vec<String> = rows.iter().map(|r| user_name(r.node.metadata.uid())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                cols.push(ColInfo{header, width: w, align_right: false, num_width: 0, unit_width: 0});
            },
            "uid" => {
                let vals: Vec<String> = rows.iter().map(|r| format!("{}", r.node.metadata.uid())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                cols.push(ColInfo{header, width: w, align_right: true, num_width: 0, unit_width: 0});
            },
            "group" => {
                let vals: Vec<String> = rows.iter().map(|r| group_name(r.node.metadata.gid())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                cols.push(ColInfo{header, width: w, align_right: false, num_width: 0, unit_width: 0});
            },
            "gid" => {
                let vals: Vec<String> = rows.iter().map(|r| format!("{}", r.node.metadata.gid())).collect();
                let w = vals.iter().map(|s| s.len()).max().unwrap_or(0).max(header.len());
                cols.push(ColInfo{header, width: w, align_right: true, num_width: 0, unit_width: 0});
            },
            "blocks" => {
                let mut maxlen = header.len();
                for r in rows.iter() {
                    if r.node.file_type=="dir" { continue; }
                    let s = format!("{}", r.node.metadata.blocks());
                    if s.len()>maxlen { maxlen=s.len(); }
                }
                // for dirs, blank (spaces) width maxlen
                cols.push(ColInfo{header, width: maxlen, align_right: true, num_width: 0, unit_width: 0});
            },
            "btime"|"ctime"|"mtime"|"atime" => {
                let w = 19.max(header.len()); // time strings 19
                cols.push(ColInfo{header, width: w, align_right: false, num_width: 0, unit_width: 0});
            },
            "git" => {
                let w = header.len(); // always 3, values blank
                cols.push(ColInfo{header, width: w, align_right: false, num_width: 0, unit_width: 0});
            },
            _ => {}
        }
    }
    let mut out = String::new();
    if show_header {
        for (i, col) in cols.iter().enumerate() {
            if i>0 { out.push(' '); }
            if col.align_right {
                out.push_str(&format!("{:>width$}", col.header, width=col.width));
            } else {
                // for time headers? They are left? Actually for btime etc, header left? Let's left for all non-right?
                // For user/group (left), header left: format!("{:<width$}")
                // For typ/perm (left? Actually T and Permissions? T is single char, header "T" left? Same. Permissions header left? But values same length, so same.
                // For btime etc, header left.
                out.push_str(&format!("{:<width$}", col.header, width=col.width));
            }
        }
        out.push(' ');
        out.push_str("Name");
        out.push('\n');
    }
    for (ri, r) in rows.iter().enumerate() {
        for (ci, det) in det_list.iter().enumerate() {
            if ci>0 { out.push(' '); }
            let col = &cols[ci];
            match det.as_str() {
                "dev" => {
                    let v = format!("{}", r.node.metadata.dev());
                    out.push_str(&format!("{:>width$}", v, width=col.width));
                },
                "ino" => {
                    let v = format!("{}", r.node.metadata.ino());
                    out.push_str(&format!("{:>width$}", v, width=col.width));
                },
                "nlink" => {
                    let v = format!("{}", r.node.metadata.nlink());
                    out.push_str(&format!("{:>width$}", v, width=col.width));
                },
                "typ" => {
                    out.push(r.node.typ_char);
                },
                "perm" => {
                    out.push_str(&perm_str(r.node.metadata.mode()));
                },
                "oct" => {
                    let v = oct_str(r.node.metadata.mode());
                    out.push_str(&format!("{:>width$}", v, width=col.width));
                },
                "user" => {
                    let v = user_name(r.node.metadata.uid());
                    out.push_str(&format!("{:<width$}", v, width=col.width));
                },
                "uid" => {
                    let v = format!("{}", r.node.metadata.uid());
                    out.push_str(&format!("{:>width$}", v, width=col.width));
                },
                "group" => {
                    let v = group_name(r.node.metadata.gid());
                    out.push_str(&format!("{:<width$}", v, width=col.width));
                },
                "gid" => {
                    let v = format!("{}", r.node.metadata.gid());
                    out.push_str(&format!("{:>width$}", v, width=col.width));
                },
                "size" => {
                    if r.node.file_type=="dir" {
                        out.push_str(&" ".repeat(col.width));
                    } else {
                        let num = &size_nums[ri];
                        let unit_s = &size_units[ri];
                        // format as num right to num_width, space, unit right? Actually unit right to unit_width? For binary, unit right? Let's do right for unit as well? For "B" vs "KiB", right gives "  B" vs "KiB". Good. For left, "B  " vs "KiB" (trailing). Observed is right ("  B"), so right.
                        let num_part = format!("{:>w$}", num, w=col.num_width);
                        let unit_part = format!("{:>w$}", unit_s, w=col.unit_width);
                        let combined = format!("{} {}", num_part, unit_part);
                        // combined len should be col.width? If header longer than total, need to pad left? Actually col.width = max(total, header len). If header longer, combined needs padding left to width.
                        if combined.len() < col.width {
                            out.push_str(&" ".repeat(col.width - combined.len()));
                        }
                        out.push_str(&combined);
                    }
                },
                "blocks" => {
                    if r.node.file_type=="dir" {
                        out.push_str(&" ".repeat(col.width));
                    } else {
                        let v = format!("{}", r.node.metadata.blocks());
                        out.push_str(&format!("{:>width$}", v, width=col.width));
                    }
                },
                "btime" => {
                    let v = format_time(file_btime(&r.node));
                    out.push_str(&format!("{:<width$}", v, width=col.width));
                },
                "ctime" => {
                    let v = format_time(file_ctime(&r.node));
                    out.push_str(&format!("{:<width$}", v, width=col.width));
                },
                "mtime" => {
                    let v = format_time(file_mtime(&r.node));
                    out.push_str(&format!("{:<width$}", v, width=col.width));
                },
                "atime" => {
                    let v = format_time(file_atime(&r.node));
                    out.push_str(&format!("{:<width$}", v, width=col.width));
                },
                "git" => {
                    out.push_str(&" ".repeat(col.width));
                },
                _ => {}
            }
        }
        out.push(' ');
        // Name column: for explicit, use single space (no align extra)? For dir listings, use align logic.
        let name_str = if is_explicit {
            // explicit: icon + single space, no align
            let mut s = String::new();
            if show_icon {
                let ic = icon_for(&r.node);
                if ic.is_empty() { s.push(' '); } else { s.push_str(ic); }
                s.push(' ');
            }
            s.push_str(&r.node.name);
            if show_suffix { s.push_str(suffix_for(&r.node)); }
            if show_sym && r.node.file_type=="symlink" {
                if let Some(chain)=symlink_chain_display(&r.node) { s.push_str(&chain); }
            }
            // for child in explicit? Explicit never has child (no collapse), so ignore is_child
            s
        } else {
            format_plain_node(&r.node, show_icon, show_suffix, show_sym, align, false, r.is_child)
        };
        out.push_str(&name_str);
        out.push('\n');
    }
    out
}

fn det_header(det: &str) -> &'static str {
    match det {
        "dev" => "Device",
        "ino" => "inode",
        "nlink" => "Link#",
        "typ" => "T",
        "perm" => "Permissions",
        "oct" => "SUGO",
        "user" => "User",
        "uid" => "UID",
        "group" => "Group",
        "gid" => "GID",
        "size" => "Size",
        "blocks" => "Blocks",
        "btime" => "Created",
        "ctime" => "Changed",
        "mtime" => "Modified",
        "atime" => "Accessed",
        "git" => "Git",
        _ => "",
    }
}
fn det_headers(list: &[String]) -> Vec<String> {
    list.iter().map(|d| det_header(d).to_string()).collect()
}

