    return p.returncode, p.stdout, p.stderr

# Fuzz with random files and args
import tempfile, random
for trial in range(20):
    td=tempfile.mkdtemp()
    # random files
    for _ in range(random.randint(3,8)):
        name = random.choice(["a.txt","b.rs","c","README.md","Cargo.toml","Cargo.lock",".hidden","mydir","link","fifo"])
        if name=="mydir":
            try: os.makedirs(f"{td}/mydir", exist_ok=True)
            except: pass
        elif name=="link":
            try: os.symlink("a.txt", f"{td}/link{random.randint(0,100)}")
            except: pass
        elif name=="fifo":
            try: os.mkfifo(f"{td}/fifo{random.randint(0,100)}")
            except: pass
        else:
            try: open(f"{td}/{name}","w").write("x"*random.randint(0,100))
            except: pass
    args = random.choice([
        [],
        ["--det","size"],
        ["--det","all"],
        ["--sort","size"],
        ["--typ","file"],
        ["--imp","1"],
        ["--icon","false"],
        ["--grid","true"],
    ])
    rc1,out1,err1=run(ORIG, args, cwd=td)
    rc2,out2,err2=run(NEW, args, cwd=td)
    if not (rc1==rc2 and out1==out2 and err1==err2):
        print(f"FAIL trial {trial} args {args}")
        print(f"ORIG {repr(out1[:1000])}")
        print(f"NEW  {repr(out2[:1000])}")
        break
else:
    print("all fuzz passed")
PY"}

